// Port of jira-mock/server.py: AND-only JQL over the pack's issues.json, plus status overrides set via the /jira/set webhook.
const jql = ($input.first().json.jql || 'project = ONB').trim();
const issues = $('Fetch issues').first().json.issues;
const overrides = $getWorkflowStaticData('global').status || {};
function match(issue, jql) {
  for (const part of jql.split(/\s+AND\s+/i)) {
    let m;
    if ((m = part.match(/^project\s*=\s*"?([\w-]+)"?$/i))) { if (issue.key.split('-')[0] !== m[1]) return false; }
    else if ((m = part.match(/^status\s*(!=|=)\s*"?([\w ]+)"?$/i))) {
      const st = (overrides[issue.key] || issue.fields.status.name).toLowerCase() === m[2].trim().toLowerCase();
      if (m[1] === '=' ? !st : st) return false; }
    else if ((m = part.match(/^(text|summary)\s*~\s*"([^"]+)"$/i))) {
      const hay = (issue.fields.summary + ' ' + (issue.fields.description || '')).toLowerCase();
      if (!hay.includes(m[2].toLowerCase())) return false; }
    // anything else (OR, ORDER BY, unknown fields) is ignored, as the Python mock does
  }
  return true;
}
const hits = issues.filter(i => match(i, jql)).map(i => ({ key: i.key, fields: { summary: i.fields.summary,
  status: { name: overrides[i.key] || i.fields.status.name }, updated: overrides[i.key] ? new Date().toISOString() : i.fields.updated } }));
return [{ json: { jql, total: hits.length, issues: hits,
  text: hits.length ? hits.map(h => `${h.key} ${h.fields.summary}. Status: ${h.fields.status.name}. Updated ${h.fields.updated.slice(0,10)}.`).join('\n') : 'nothing found' } }];

// GET .../jira/set?key=ONB-15&status=Open  flips one issue's status until the workflow's static data is cleared.
const q = $input.first().json.query || {};
const data = $getWorkflowStaticData('global');
data.status = data.status || {};
if (q.key && q.status) data.status[q.key] = q.status;
if (q.reset) data.status = {};
return [{ json: { status: data.status } }];
